const grid=document.getElementById("productGrid");
function renderProducts(){if(!grid)return;const lang=document.documentElement.lang==="sk"?"sk":"en";grid.innerHTML=products.map((p,i)=>{const cover=coverMap[p[4]];const art=cover?`<div class="product-art real-product-cover"><img src="${cover}" alt="${p[0]} product cover" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block"></div>`:`<div class="product-art art-${palette[i%palette.length]}"><small>MiQd.</small><strong>${p[0]}</strong><span>${p[6]}</span><i>${String(i+1).padStart(2,"0")}</i></div>`;return `<article class="product-card ${i<3?"featured":""}" data-category="${p[3]}">${art}<b>${p[3].toUpperCase()}</b><h3>${p[0]}</h3><p>${lang==="sk"?p[2]:p[1]}</p><div class="card-bottom"><strong class="price">${p[5]}</strong><a class="card-action" href="https://payhip.com/b/${p[4]}?utm_source=website&utm_medium=catalog&utm_campaign=${encodeURIComponent(p[3])}" target="_blank" rel="noopener">${lang==="sk"?"Kúpiť na Payhip ↗":"Buy on Payhip ↗"}</a></div></article>`}).join("");applyFilter(document.querySelector(".filters .active")?.dataset.filter||"all");observeCards()}
const toggle=document.getElementById("langToggle"),menu=document.getElementById("langMenu"),langButtons=document.querySelectorAll("[data-lang]");
if(toggle&&menu){toggle.addEventListener("click",e=>{e.stopPropagation();const open=menu.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open))});document.addEventListener("click",()=>{menu.classList.remove("open");toggle.setAttribute("aria-expanded","false")});menu.addEventListener("click",e=>e.stopPropagation())}
function setLanguage(lang){document.documentElement.lang=lang;document.querySelectorAll("[data-en][data-sk]").forEach(el=>el.innerHTML=el.dataset[lang]);langButtons.forEach(btn=>btn.classList.toggle("active",btn.dataset.lang===lang));try{localStorage.setItem("miqd-lang",lang)}catch(e){}if(menu)menu.classList.remove("open");renderProducts()}
let saved="en";try{saved=localStorage.getItem("miqd-lang")||((navigator.language||"").toLowerCase().startsWith("sk")?"sk":"en")}catch(e){}setLanguage(saved==="sk"?"sk":"en");langButtons.forEach(btn=>btn.addEventListener("click",()=>setLanguage(btn.dataset.lang)));
function applyFilter(filter){document.querySelectorAll(".product-card").forEach(card=>card.hidden=filter!=="all"&&card.dataset.category!==filter)}
document.querySelectorAll("[data-filter]").forEach(btn=>btn.addEventListener("click",()=>{document.querySelectorAll("[data-filter]").forEach(b=>b.classList.toggle("active",b===btn));applyFilter(btn.dataset.filter)}));const requestedFilter=new URLSearchParams(location.search).get("filter");if(requestedFilter){const filterButton=document.querySelector(`[data-filter="${requestedFilter}"]`);if(filterButton){document.querySelectorAll("[data-filter]").forEach(b=>b.classList.toggle("active",b===filterButton));applyFilter(requestedFilter)}}
function observeCards(){const cards=document.querySelectorAll(".product-card,.grid article,.steps>div,.why>div,.trust>div");if(!("IntersectionObserver"in window)){cards.forEach(c=>c.classList.add("revealed"));return}const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add("revealed");observer.unobserve(e.target)}}),{threshold:.05});cards.forEach((c,i)=>{c.classList.add("reveal");c.style.setProperty("--delay",`${Math.min(i%3,2)*45}ms`);observer.observe(c)})}observeCards();
